"""Compare 0.11.0 (rel) vs the depth fix (fix) outputs in bisect-out/cmp: components and props changed, top examples."""
import json
import sys

DIR = '/Users/gabe/Projects/caliper-fixtures/shrink/bisect-out/cmp'


def load(path):
    d = json.load(open(path))
    d.pop('stats', None)
    return d


def props_of(d):
    out = {}
    for key, comp in d['components'].items():
        out[key] = {d['props'][pid]['name']: d['props'][pid] for pid in comp['props']}
    return out


def first_diff(a, b, path='type'):
    """Path and the two nodes where the types first differ."""
    if type(a) is not type(b):
        return path, a, b
    if isinstance(a, dict):
        if a.get('kind') != b.get('kind'):
            return path, a, b
        for k in sorted(set(a) | set(b)):
            if a.get(k) != b.get(k):
                if k not in a or k not in b:
                    return f'{path}.{k}', a, b
                return first_diff(a[k], b[k], f'{path}.{k}')
        return None
    if isinstance(a, list):
        if len(a) != len(b):
            return path, a, b
        for i, (x, y) in enumerate(zip(a, b)):
            r = first_diff(x, y, f'{path}[{i}]')
            if r:
                return r
        return None
    return (path, a, b) if a != b else None


def describe(node):
    if isinstance(node, dict):
        kind = node.get('kind')
        if kind == 'truncated':
            return f"truncated {json.dumps({k: v for k, v in node.items() if k != 'kind'})[:120]}"
        if kind == 'object':
            fields = node.get('fields') or node.get('properties') or []
            return f'object({len(fields)} fields)'
        return str(kind)
    if isinstance(node, list):
        return f'list({len(node)})'
    return json.dumps(node)[:60]


def size(node):
    return len(json.dumps(node))


def main(name):
    rel, fix = load(f'{DIR}/{name}.rel.json'), load(f'{DIR}/{name}.fix.json')
    if rel == fix:
        print(f'## {name}: identical (stats dropped)')
        return
    pr, pf = props_of(rel), props_of(fix)
    comps_changed, rows = set(), []
    for key in sorted(set(pr) | set(pf)):
        a, b = pr.get(key, {}), pf.get(key, {})
        for prop in sorted(set(a) | set(b)):
            x, y = a.get(prop), b.get(prop)
            if x == y:
                continue
            comps_changed.add(key)
            if x is None or y is None:
                rows.append((key, prop, 'missing' if x is None else 'present', 'present' if y is not None else 'missing', '', False, 0))
                continue
            d = first_diff(x.get('type'), y.get('type'))
            own = not any('/node_modules/' in decl.get('fileName', '') for decl in x.get('declarations') or [])
            if d is None:
                rows.append((key, prop, 'non-type field', '', '', own, 0))
                continue
            path, na, nb = d
            rows.append((key, prop, describe(na), describe(nb), path, own, size(x.get('type')) - size(y.get('type'))))
    other = {k for k in rel if k not in ('components', 'props') and rel[k] != fix.get(k)}
    print(f'## {name}: {len(comps_changed)} of {len(pr)} components changed, {len(rows)} props changed; other keys differing: {sorted(other)}')
    print(f'- props declared in project files (own): {sum(1 for r in rows if r[5])} of {len(rows)}')
    for r in sorted(rows, key=lambda r: -r[6])[:10]:
        print(f'- {r[0]} . {r[1]}: {r[2]} -> {r[3]} at {r[4]} (own prop: {r[5]}, JSON -{r[6]} B)')


for n in sys.argv[1:]:
    main(n)

